const dlq = new Queue(this, 'ClaimsDLQ');
const work = new Queue(this, 'ClaimsWork', {
  deadLetterQueue: { queue: dlq, maxReceiveCount: 3 },
});
processor.addEventSource(new SqsEventSource(work, { maxConcurrency: 50 }));

